import{DataManager,defaultData,safeImageSrc,whatsappUrl}from"./dataManager.js";import{UIManager}from"./uiManager.js";import{initVisibility}from"./visibility.js";const dataManager=new DataManager,uiManager=new UIManager(dataManager);document.addEventListener("DOMContentLoaded",async()=>{try{uiManager.initialize(),await Promise.allSettled([initVisibility(),dataManager.initialize()])}catch(a){console.error("Erro ao iniciar a página:",a)}});export{dataManager,uiManager,defaultData,safeImageSrc,whatsappUrl};